import kotlinx_reflect_gradle_plugin_test_commonMain.KotlinxReflectForModule
import net.akehurst.kotlinx.reflect.KotlinxReflect
import kotlin.coroutines.Continuation
import kotlin.coroutines.EmptyCoroutineContext
import kotlin.coroutines.startCoroutine

/** Use only the registrations generated by KSP, on every platform (no kotlin-reflect on JVM, no JS-name fallback). */
fun useGeneratedRegistrations() {
    KotlinxReflect.forceRegistry = true
    KotlinxReflectForModule.registerUsedClasses()
}

/** Runs a suspend block that never actually suspends, without needing kotlinx-coroutines. */
fun <T> runSuspend(block: suspend () -> T): T {
    var result: Result<T>? = null
    block.startCoroutine(Continuation(EmptyCoroutineContext) { result = it })
    return result!!.getOrThrow()
}

const val PKG = "net.akehurst.kotlinx.reflect.gradle.plugin.test.moduleForReflection"
